import { projectMaturityFromLevel } from './scientificProjectLevels';

/**
 * @param {object} p
 */
function deepProject(p) {
  const level = p.level;
  const maturity = projectMaturityFromLevel(level);
  return {
    id: p.id,
    needs: p.interests || p.needs || [],
    title: p.title,
    level,
    maturity: p.maturity || maturity.label,
    type: p.type || 'projeto computacional',
    interests: p.interests || p.needs || [],
    prerequisites: p.prerequisites || [],
    theoryTopics: p.theoryTopics || [],
    tools: p.tools || ['Python'],
    expectedOutput: p.expectedOutput || '',
    difficulty: p.difficulty || 'média',
    duration: p.duration || '2–4 semanas',
    nextSteps: p.nextSteps || [],
    possibleDeliverables: p.possibleDeliverables || ['Notebook Jupyter', 'Relatório PDF'],
    professorQuestions: p.professorQuestions || [],
    why: p.why || '',
    disciplines: p.disciplines || [],
  };
}

